def bsearch(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
print(bsearch([1, 3, 5, 7], 5))   # 2

def ordered_left(nums, l, m):
    return nums[l] <= nums[m]   # True: [l,m] 单调不减
print(ordered_left([4, 5, 6, 7, 0, 1, 2], 0, 3))   # True

